<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { authState } from '@/stores/auth'
import { Plus, Refresh } from '@element-plus/icons-vue'
import { oaApi } from '@/api/oa'
import { canOA, messageOf, useOACommands } from '@/utils/oa'
import { leaveTypeCode, leaveTypeLabel, leaveTypeLabels } from '@/utils/leave-types'
import type { Balance, Named } from '@/types/oa'
const {busy,error,run}=useOACommands(); const rows=ref<Balance[]>([]); const users=ref<Named[]>([]); const selectedUser=ref(''); const showForm=ref(false); const form=ref({leave_type:'annual',year:new Date().getFullYear(),total:0,reason:'',user_id:''}); const writable=computed(()=>canOA('leave_balance','write')); const canRead=computed(()=>canOA('leave_balance'))
async function load(){error.value='';if(!canRead.value){error.value='当前账号没有额度读取权限';return}try{if(writable.value){const o=await oaApi.options('leave_balance','write');users.value=o.users}rows.value=await oaApi.balances(selectedUser.value||undefined)}catch(e){users.value=[];error.value=messageOf(e)}}
const targetRows=ref<Balance[]>([]), targetLoading=ref(false), targetReady=ref(false)
const leaveTypes=computed(()=>[...new Set([...Object.keys(leaveTypeLabels),...targetRows.value.map(row=>leaveTypeCode(row.leave_type))])])
let targetRequest=0
async function loadTarget(){const request=++targetRequest;targetReady.value=false;targetLoading.value=true;try{const items=await oaApi.balances(form.value.user_id);if(request===targetRequest){targetRows.value=items;targetReady.value=true;setTotal()}}catch(e){error.value=messageOf(e)}finally{if(request===targetRequest)targetLoading.value=false}}
function setTotal(){form.value.total=targetRows.value.find(r=>leaveTypeCode(r.leave_type)===leaveTypeCode(form.value.leave_type)&&r.year===form.value.year)?.total||0}
function selectLeaveType(value:string){form.value.leave_type=leaveTypeCode(value);setTotal()}
watch(()=>form.value.user_id,()=>{if(showForm.value)void loadTarget()})
watch(()=>[form.value.leave_type,form.value.year],setTotal)
function openAdjust(){if(!writable.value)return;form.value={leave_type:'annual',year:new Date().getFullYear(),total:0,reason:'',user_id:selectedUser.value||authState.user?.user_id||''};showForm.value=true;void loadTarget()}
async function save(){if(!writable.value||!targetReady.value||targetLoading.value||!form.value.user_id||!form.value.leave_type||!form.value.reason.trim())return;const current=targetRows.value.find(r=>r.user_id===form.value.user_id&&leaveTypeCode(r.leave_type)===leaveTypeCode(form.value.leave_type)&&r.year===form.value.year);const result=await run(`balance:${form.value.user_id}`,{expected_revision:current?.revision||0,...form.value,leave_type:leaveTypeCode(form.value.leave_type)},p=>oaApi.adjust(p));if(result){showForm.value=false;await load()}}
onMounted(load)
</script>
<template><main class="workbench manual-oa" v-loading="busy"><header class="page-heading"><div><span class="eyebrow">年度额度</span><h1>请假额度</h1><p class="muted">额度必须按人员、年度和假种显式初始化，系统不会自动补发。</p></div><div class="actions"><el-button :icon="Refresh" @click="load">刷新</el-button><el-button v-if="writable" data-testid="adjust-balance" type="primary" :icon="Plus" @click="openAdjust">调整额度</el-button></div></header><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="oa-section"><el-select v-if="writable" v-model="selectedUser" placeholder="选择人员" clearable @change="load"><el-option v-for="user in users" :key="user.id" :label="user.name" :value="user.id"/></el-select><el-table :data="rows" empty-text="暂无额度"><el-table-column prop="year" label="年度" width="100"/><el-table-column label="假种"><template #default="{row}">{{leaveTypeLabel(row.leave_type)}}</template></el-table-column><el-table-column prop="total" label="总额"/><el-table-column prop="used" label="已使用"/><el-table-column prop="reserved" label="已占用"/><el-table-column prop="available" label="可用"/></el-table></section><el-dialog v-model="showForm" title="调整年度额度" width="520px"><el-form label-position="top"><el-form-item label="人员"><el-select v-model="form.user_id"><el-option v-for="user in users" :key="user.id" :label="user.name" :value="user.id"/></el-select></el-form-item><div class="oa-grid"><el-form-item label="额度假种"><el-select v-model="form.leave_type" filterable allow-create aria-label="额度假种" @change="selectLeaveType"><el-option v-for="type in leaveTypes" :key="type" :label="leaveTypeLabel(type)" :value="type"/></el-select></el-form-item><el-form-item label="年度"><el-input-number v-model="form.year" :min="2000" :max="2200"/></el-form-item><el-form-item label="总天数"><el-input-number v-model="form.total" aria-label="总天数" :min="0" :max="3660"/></el-form-item></div><el-form-item label="调整原因"><el-input v-model="form.reason" aria-label="调整原因"/></el-form-item></el-form><template #footer><el-button @click="showForm=false">取消</el-button><el-button data-testid="save-balance" type="primary" :disabled="busy||targetLoading||!targetReady||!form.user_id||!form.leave_type||!form.reason.trim()" @click="save">保存</el-button></template></el-dialog></main>
</template>
